const wc = $('When Called').first().json;

// Global safety ceiling (runaway guard against a malformed/hallucinated block list). NOT a per-impact
// business cap: impact drives image MODEL + RESOLUTION (inside Invoke Model), never count.
let ceiling = 20;
try { const c = $('Lookup Image Config').first().json.ceiling; if (c != null && !isNaN(Number(c))) ceiling = Number(c); } catch (e) {}

// --- parseBlockArray: robust recovery of the model's block array. KEEP IN SYNC with
// Render Agent Output (v1) 'Parse Blocks' (same block protocol, ADR-053 #4). ---
// Handles three model defects, escalating only on failure: (1) a ```json fence; (2) a prose
// preamble/suffix around the array; (3) UNESCAPED double-quotes inside string values (Polish
// typographic mixing). The quote repair is SCHEMA-AWARE: an in-string " is the real string
// terminator ONLY when the next non-ws token is grammar-consistent — a closing } or ], a : (key
// close), or a , whose following token is structural ({ [ } ]) or one of the KNOWN block keys.
// Otherwise the " is literal prose and is escaped. Tying the rule to the fixed key set fixes the
// "quote-before-comma" misfire a generic next-char-is-structural rule makes (observed live, task
// 869dux9ne: a typographic close-quote before a comma collapsed a valid array to plain text).
function parseBlockArray(input) {
  const warn = [];
  let raw = String(input == null ? '' : input).trim();
  const BS = String.fromCharCode(92);
  const KNOWN = { type: 1, md: 1, text: 1, ref: 1, file_id: 1, mode: 1, caption: 1, alt: 1, source_ref: 1, order: 1, prompt: 1, aspect: 1, size: 1, reference_refs: 1 };
  function tryParse(s) { try { return { ok: true, v: JSON.parse(s) }; } catch (e) { return { ok: false }; } }
  const fence = raw.match(/^```[a-zA-Z]*\s*([\s\S]*?)\s*```\s*$/);
  if (fence) raw = fence[1].trim();
  let r = tryParse(raw);
  if (!r.ok) {
    const m = raw.match(/\[\s*[\{\[]/);
    if (m) { const e = raw.lastIndexOf(']'); if (e > m.index) { const s = raw.slice(m.index, e + 1); const pr = tryParse(s); if (pr.ok && Array.isArray(pr.v)) { raw = s; r = pr; warn.push({ source: 'output-adapter/preamble-stripped', err: 'model dodal tekst przed/po tablicy blokow JSON — odzyskano bloki przez wyciecie tablicy; rozwaz dociagniecie promptu agenta (ma zwracac sama tablice blokow)', severity: 'WARN' }); } } }
  }
  if (!r.ok) {
    function skipWs(s, i) { while (i < s.length) { const c = s.charCodeAt(i); if (c === 32 || c === 9 || c === 10 || c === 13) i++; else break; } return i; }
    function knownKeyAt(s, i) { if (s[i] !== '"') return false; let j = i + 1, k = ''; while (j < s.length) { const c = s[j]; if (c === '"') break; if (c === BS) { j += 2; continue; } k += c; j++; } return KNOWN[k] === 1; }
    let o = '', inStr = false, esc = false;
    for (let i = 0; i < raw.length; i++) {
      const ch = raw[i];
      if (!inStr) { o += ch; if (ch === '"') inStr = true; continue; }
      if (esc) { o += ch; esc = false; continue; }
      if (ch === BS) { o += ch; esc = true; continue; }
      if (ch.charCodeAt(0) < 32) { o += BS + 'u' + ('000' + ch.charCodeAt(0).toString(16)).slice(-4); continue; }
      if (ch === '"') {
        const j = skipWs(raw, i + 1);
        const nx = j < raw.length ? raw[j] : '';
        let term = false;
        if (nx === '' || nx === '}' || nx === ']' || nx === ':') term = true;
        else if (nx === ',') { const k = skipWs(raw, j + 1); const af = k < raw.length ? raw[k] : ''; if (af === '' || af === '{' || af === '[' || af === '}' || af === ']') term = true; else if (af === '"') term = knownKeyAt(raw, k); else term = false; }
        if (term) { o += '"'; inStr = false; continue; }
        o += BS + '"'; continue;
      }
      o += ch;
    }
    r = tryParse(o);
  }
  let b = r.ok ? r.v : null;
  if (b && !Array.isArray(b) && Array.isArray(b.blocks)) b = b.blocks;
  return { blocks: Array.isArray(b) ? b : null, raw: raw, warnings: warn };
}

const parsedBlocks = parseBlockArray(wc.output_blocks_json);
const parse_warnings = parsedBlocks.warnings.map(function (w) { return (w.source || 'multimodal/parse') + ': ' + (w.err || ''); });
let blocks = parsedBlocks.blocks;
if (!Array.isArray(blocks)) {
  parse_warnings.push('multimodal/parse-fallback: output_blocks_json nie jest tablica blokow JSON — dostarczono jako zwykly tekst');
  blocks = [{ type: 'text', md: parsedBlocks.raw }];
}

let inputRefs = [];
try { inputRefs = JSON.parse(wc.input_image_refs_json || '[]'); } catch (e) { inputRefs = []; }
if (!Array.isArray(inputRefs)) inputRefs = [];

// Lookup map for embed_input resolution: by source_ref (attachment id) AND by ref (url).
const lookup = {};
for (const r of inputRefs) {
  if (!r) continue;
  if (r.source_ref) lookup[String(r.source_ref)] = r;
  if (r.ref) lookup[String(r.ref)] = r;
}
const lookup_map = JSON.stringify(lookup);

const pass = {
  impact: wc.impact || '',
  clickup_task_id: wc.clickup_task_id || '',
  triggered_by: wc.triggered_by || 'image_gen',
  invocation_type: wc.invocation_type || 'explicit',
  caller_user_id: wc.caller_user_id || '',
  process_type: wc.process_type || ''
};

const out = [];
let genCount = 0;
for (let idx = 0; idx < blocks.length; idx++) {
  const b = blocks[idx] || {};
  const order = (b.order != null) ? Number(b.order) : (idx + 1);
  const type = b.type;
  if (type === 'text') {
    out.push({ json: Object.assign({ route: 'text', block_type: 'text', block_order: order, md: b.md || '' }, pass) });
  } else if (type === 'image' && b.mode === 'embed_input') {
    out.push({ json: Object.assign({ route: 'embed', block_type: 'embed_input', block_order: order,
      ref: b.ref || '', source_ref: b.source_ref || '', caption: b.caption || '', alt: b.alt || '', lookup_map }, pass) });
  } else if (type === 'image' && b.mode === 'generate') {
    genCount++;
    const active = genCount <= ceiling;
    out.push({ json: Object.assign({ route: active ? 'generate' : 'drop', block_type: 'generate', block_order: order,
      is_active: active, prompt: b.prompt || '', aspect: b.aspect || '', size: b.size || '', caption: b.caption || '', alt: b.alt || '',
      placeholder_id: 'gen_' + (genCount - 1), reference_refs: Array.isArray(b.reference_refs) ? b.reference_refs : [], lookup_map }, pass) });
  }
  // unknown block types are skipped
}

// Surface parse warnings (recovery or total-failure fallback) on a dedicated text carrier (order -1,
// empty md renders nothing). A 0-item node never executes downstream (CLAUDE.md), so the WARN must ride
// an item that survives Classify Block -> Assemble Output; the text route passes through unchanged.
if (parse_warnings.length) {
  out.unshift({ json: Object.assign({ route: 'text', block_type: 'text', block_order: -1, md: '', parse_warnings: parse_warnings }, pass) });
}
return out;

const block = $json;
let map = {};
try { map = JSON.parse(block.lookup_map || '{}'); } catch (e) { map = {}; }
const input = map[block.source_ref] || map[block.ref] || null;
if (!input) {
  return { json: { block_type: 'embed_failed', block_order: block.block_order,
    warning: 'multimodal/embed-ref-not-found: ' + (block.ref || block.source_ref || '(empty)') } };
}
return { json: { block_type: 'embed_resolved', block_order: block.block_order,
  att_id: input.source_ref || '', att_url: input.ref || '', caption: block.caption || '', alt: block.alt || '' } };

const items = $input.all().map(function(i){ return i.json; });
const first = items[0] || {};
let cap = 5;
try { const c = $('Lookup Image Config').first().json.concurrency_cap; if (c != null && !isNaN(Number(c))) cap = Number(c); } catch (e) {}

// ADR-052 Block 2: reusable, caller-agnostic reference resolver. Takes a ref (source_ref or url string, or
// an object with .source_ref/.ref) + the input-image lookup map (keyed by source_ref AND url, values = the
// input-ref objects) and returns a usable image URL or null. No n8n/$json/item context inside -- the future
// generate_image tool handler reuses it verbatim with a file_id-derived lookup (ADR-053/054).
function resolveReferenceToUrl(ref, lookup) {
  if (!ref || !lookup) return null;
  const key = (typeof ref === 'string') ? ref : (ref.source_ref || ref.ref || '');
  const hit = lookup[key] || (typeof ref === 'object' ? (lookup[ref.ref] || lookup[ref.source_ref]) : null) || null;
  if (!hit) return null;
  if (typeof hit === 'string') return hit;
  return hit.ref || null;
}

const prebatch_warnings = [];
const requests = items.map(function(b){
  let lookup = {};
  try { lookup = JSON.parse(b.lookup_map || '{}'); } catch (e) { lookup = {}; }
  const refs = Array.isArray(b.reference_refs) ? b.reference_refs : [];
  const reference_urls = [];
  for (const ref of refs) {
    const url = resolveReferenceToUrl(ref, lookup);
    if (url) reference_urls.push(url);
    else prebatch_warnings.push({ placeholder_id: b.placeholder_id || '',
      warning: 'multimodal/reference-ref-not-found: ' + (typeof ref === 'string' ? ref : JSON.stringify(ref)) });
  }
  return {
    placeholder_id: b.placeholder_id || '', prompt: b.prompt || '',
    size: b.size || '', aspect: b.aspect || '',
    caption: b.caption || '', alt: b.alt || '',
    block_order: (b.block_order != null) ? b.block_order : 99,
    reference_urls: reference_urls
  };
});
return [{ json: {
  requests_json: JSON.stringify(requests),
  prebatch_warnings: prebatch_warnings,
  impact: first.impact || '',
  concurrency_cap: cap,
  clickup_task_id: first.clickup_task_id || '',
  triggered_by: first.triggered_by || 'image_gen',
  invocation_type: first.invocation_type || 'explicit',
  caller_user_id: first.caller_user_id || '',
  process_type: first.process_type || ''
} }];

const results = $input.all().map(function(i){ return i.json; });
// ADR-052 Block 2: prebatch reference warnings (a ref dropped before the batch -- reference-ref-not-found)
// ride on Build Batch Request's output, NOT through the batch (executeWorkflow replaces the item with the
// sub-workflow's results). Read them back by node reference and fold into each placeholder's warnings[].
let prebatch = [];
try { const pb = $('Build Batch Request').first().json.prebatch_warnings; if (Array.isArray(pb)) prebatch = pb; } catch (e) { prebatch = []; }
function prebatchFor(pid) { const o = []; for (const p of prebatch) { if (p && p.placeholder_id === pid) o.push(p.warning); } return o; }
const out = [];
// Batch THROW path: Call Generate Batch (onError=continueRegularOutput) passed its INPUT request item
// through instead of per-image results (only the Vault-key-missing throw, already CRITICALed by the
// batch's errorWorkflow). Detect by the request shape and degrade to per-placeholder failures.
if (results.length && results[0].requests_json != null && results[0].success === undefined) {
  let reqs = [];
  try { reqs = JSON.parse(results[0].requests_json || '[]'); } catch (e) { reqs = []; }
  for (const r of reqs) {
    const pid = r.placeholder_id || '';
    out.push({ json: { block_type: 'generate_failed', block_order: (r.block_order != null) ? r.block_order : 99,
      placeholder_id: pid, caption: r.caption || '', alt: r.alt || '', cost_pln: 0,
      warnings: ['multimodal/image-gen-failed: batch unavailable'].concat(prebatchFor(pid)) } });
  }
  return out;
}
for (const res of results) {
  const pid = res.placeholder_id || '';
  const pbw = prebatchFor(pid);
  if (!res.success || !res.b64_json) {
    const base = (Array.isArray(res.warnings) && res.warnings.length) ? res.warnings : ['multimodal/image-gen-failed: no output'];
    out.push({ json: { block_type: 'generate_failed', block_order: (res.block_order != null) ? res.block_order : 99,
      placeholder_id: pid, caption: res.caption || '', alt: res.alt || '',
      cost_pln: Number(res.cost_pln || 0),
      warnings: base.concat(pbw) } });
  } else {
    const base = Array.isArray(res.warnings) ? res.warnings : [];
    out.push({ json: { block_type: 'generate_success', block_order: res.block_order, placeholder_id: pid,
      b64_json: res.b64_json, mime: res.mime || 'image/png', caption: res.caption || '', alt: res.alt || '',
      cost_pln: Number(res.cost_pln || 0), image_model: res.model || '', resolution_note: res.resolution_note || '',
      warnings: base.concat(pbw) } });
  }
}
return out;

return { json: { block_type: 'generate_dropped', block_order: $json.block_order,
  md: '[Obraz pominięty — przekroczono limit bezpieczeństwa]',
  warning: 'multimodal/image-count-ceiling: safety ceiling reached at order ' + $json.block_order } };

const items = $input.all().map(i => i.json);
items.sort((a, b) => ((a.block_order == null ? 99 : a.block_order) - (b.block_order == null ? 99 : b.block_order)));

const FENCE = String.fromCharCode(96, 96, 96);
const LINK = /\[([^\]]+)\]\(([^)]+)\)/;
const BOLD = /\*\*([^*]+)\*\*/;
const CODE = /\x60([^\x60]+)\x60/;
const ITAL = /\*([^*]+)\*|_([^_]+)_/;
function inlineOps(t) {
  const out = [];
  let rest = String(t);
  while (rest.length) {
    let best = null, kind = null;
    const cands = [[LINK,'link'],[BOLD,'bold'],[CODE,'code'],[ITAL,'ital']];
    for (const c of cands) { const m = c[0].exec(rest); if (m && (best === null || m.index < best.index)) { best = m; kind = c[1]; } }
    if (!best) { out.push({ text: rest }); break; }
    if (best.index > 0) out.push({ text: rest.slice(0, best.index) });
    if (kind === 'link') out.push({ text: best[1], attributes: { link: best[2] } });
    else if (kind === 'bold') out.push({ text: best[1], attributes: { bold: true } });
    else if (kind === 'code') out.push({ text: best[1], attributes: { code: true } });
    else out.push({ text: best[1] || best[2], attributes: { italic: true } });
    rest = rest.slice(best.index + best[0].length);
  }
  return out.length ? out : [{ text: '' }];
}
function isRow(s){ const t=s.trim(); return t.length>1 && t.charAt(0)==='|' && t.charAt(t.length-1)==='|'; }
function isSep(s){ const t=s.trim(); return /^[|\s:-]+$/.test(t) && t.indexOf('-')>=0; }
function cellsOf(s){ return s.trim().replace(/^\|/,'').replace(/\|$/,'').split('|').map(function(c){return c.trim();}); }
function mdToOps(md) {
  const ops = [];
  function emit(inline, attrs) { for (const o of inline) ops.push(o); ops.push(attrs ? { text: '\n', attributes: attrs } : { text: '\n' }); }
  const L = String(md).replace(/\r/g,'').split('\n');
  let i=0, gRow=0, inCode=false;
  while (i < L.length) {
    const s = L[i];
    if (s.trim().indexOf(FENCE) === 0) { inCode = !inCode; i++; continue; }
    if (inCode) { ops.push({ text: s }); ops.push({ text: '\n', attributes: { 'code-block': 'plain' } }); i++; continue; }
    if (isRow(s) && i+1 < L.length && isSep(L[i+1])) {
      const rows=[]; let j=i;
      while (j < L.length && isRow(L[j])) { rows.push(L[j]); j++; }
      for (let r=0; r<rows.length; r++) {
        if (r===1) continue;
        gRow++;
        const cs = cellsOf(rows[r]);
        for (const c of cs) { const io = inlineOps(c); for (const o of io) ops.push(o); ops.push({ text: '\n', attributes: { table: 'row-'+gRow } }); }
      }
      i=j; continue;
    }
    const t = s.replace(/^\s+/,'');
    let m;
    if (t.charAt(0)==='#') { const h=t.match(/^(#{1,6})\s+(.*)$/); if (h) { emit(inlineOps(h[2]), { header: Math.min(h[1].length,3) }); i++; continue; } }
    if ((m = t.match(/^[-*+]\s+(.*)$/))) { emit(inlineOps(m[1]), { list: 'bullet' }); i++; continue; }
    if ((m = t.match(/^\d+\.\s+(.*)$/))) { emit(inlineOps(m[1]), { list: 'ordered' }); i++; continue; }
    if (t.charAt(0)==='>') { emit(inlineOps(t.replace(/^>\s?/,'')), { blockquote: true }); i++; continue; }
    if (/^([-*_])\1{2,}$/.test(s.trim())) { i++; continue; }
    if (s.trim()==='') { i++; continue; }
    emit(inlineOps(s), null);
    i++;
  }
  return ops;
}

const image_manifest = [];
const rendered_delta = [];
const warnings = [];
const image_models_set = {};
let total_image_cost_pln = 0;

for (const block of items) {
  if (Array.isArray(block.parse_warnings)) { for (const w of block.parse_warnings) warnings.push(w); }
  switch (block.block_type) {
    case 'text':
      for (const op of mdToOps(block.md || '')) rendered_delta.push(op);
      break;
    case 'embed_resolved':
      rendered_delta.push({ type: 'attachment', attachment: { id: block.att_id, url: block.att_url } });
      if (block.caption) rendered_delta.push({ text: block.caption + '\n', attributes: { italic: true } });
      else rendered_delta.push({ text: '\n' });
      break;
    case 'embed_failed':
      rendered_delta.push({ text: '[Obraz niedostępny]\n', attributes: { italic: true } });
      warnings.push(block.warning);
      break;
    case 'generate_success':
      image_manifest.push({ placeholder_id: block.placeholder_id, b64: block.b64_json, mime: block.mime, caption: block.caption, alt: block.alt });
      rendered_delta.push({ type: 'image_ref', placeholder_id: block.placeholder_id });
      if (block.caption) rendered_delta.push({ text: block.caption + '\n', attributes: { italic: true } });
      else rendered_delta.push({ text: '\n' });
      if (block.resolution_note) { rendered_delta.push({ text: block.resolution_note + '\n', attributes: { italic: true } }); warnings.push('image-batch/resolution-adjusted: ' + block.resolution_note); }
      if (Array.isArray(block.warnings)) { for (const w of block.warnings) warnings.push(w); }
      total_image_cost_pln += Number(block.cost_pln || 0);
      if (block.image_model) image_models_set[block.image_model] = true;
      break;
    case 'generate_failed':
      rendered_delta.push({ text: '[Generowanie obrazu nieudane]\n', attributes: { italic: true } });
      if (Array.isArray(block.warnings)) { for (const w of block.warnings) warnings.push(w); }
      else if (block.warning) warnings.push(block.warning);
      total_image_cost_pln += Number(block.cost_pln || 0);
      break;
    case 'generate_dropped':
      rendered_delta.push({ text: (block.md || '') + '\n', attributes: { italic: true } });
      warnings.push(block.warning);
      break;
  }
}

return [{ json: { image_manifest, rendered_delta, total_image_cost_pln, image_models: Object.keys(image_models_set), warnings } }];
